SELECT a.account_type, CASE WHEN a.balance >= 61000 THEN 'high' WHEN a.balance >= 28000 THEN 'mid' ELSE 'low' END AS balance_bucket, SUM(t.amount) AS total_amount, MIN(t.amount) AS min_amount FROM transactions t INNER JOIN accounts a ON a.id = t.account_id INNER JOIN customers c ON a.customer_id = c.id WHERE a.status NOT IN ('CLOSED', 'OPEN') GROUP BY a.account_type, CASE WHEN a.balance >= 61000 THEN 'high' WHEN a.balance >= 28000 THEN 'mid' ELSE 'low' END;
